// Arduino Sketch
void setup() {
  pinMode(LED_BUILTIN, OUTPUT); // Настраиваем встроенный светодиод (подключен к пину 13) как выход
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH); // Включаем светодиод (подаём напряжение 5 В)
  delay(1000);                   // Ждём 1 секунду (1000 миллисекунд)
  digitalWrite(LED_BUILTIN, LOW);  // Выключаем светодиод (снимаем напряжение)
  delay(1000);                   // Ждём ещё 1 секунду
}
